const fs = require('fs'), cp = require('child_process');
const V1 = '{"name":"demo","retries":3}';
const V2 = '{"name":"demo","retries":3,"enabled":true,"version":2}';
const P = 'config.json';

console.log('[pwd]', process.cwd());
console.log('[ls]', fs.readdirSync('.').join('  '));

const existsBefore = fs.existsSync(P);
console.log('[exists config.json before]', existsBefore);

if (existsBefore) {
  const cur = fs.readFileSync(P, 'utf8');
  console.log('[existing raw]', JSON.stringify(cur));
  if (cur !== V1 && cur !== V2) {
    console.log('STOP: existing config.json differs from v1/v2 target; not overwriting. Awaiting confirmation.');
    process.exit(0);
  }
  console.log('[existing matches target path - proceed]');
} else {
  fs.writeFileSync(P, V1);
  console.log('[wrote v1]', JSON.stringify(fs.readFileSync(P, 'utf8')));
}

// ---- stage 1 validation (parse v1/v2 state) ----
let raw = fs.readFileSync(P, 'utf8');
let o = JSON.parse(raw);
console.log('[stage1 parse]', JSON.stringify(o), '| name:', typeof o.name, o.name, '| retries:', typeof o.retries, o.retries);

// ---- stage 2 upgrade ----
if (raw !== V2) { fs.writeFileSync(P, V2); console.log('[wrote v2]'); }

// ---- stage 2 validation ----
const raw2 = fs.readFileSync(P, 'utf8');
const o2 = JSON.parse(raw2);
const keys = Object.keys(o2);
const checks = {
  exact_text: raw2 === V2,
  name_string_demo: typeof o2.name === 'string' && o2.name === 'demo',
  retries_number_3: typeof o2.retries === 'number' && o2.retries === 3,
  enabled_boolean_true: typeof o2.enabled === 'boolean' && o2.enabled === true,
  version_number_2: typeof o2.version === 'number' && o2.version === 2,
  key_order: keys.join(',') === 'name,retries,enabled,version',
  no_extra_keys: keys.length === 4
};
console.log('[checks]', JSON.stringify(checks));

// ---- stage 3 evidence ----
function sh(cmd) { try { return cp.execSync(cmd, { encoding: 'utf8' }); } catch (e) { return null; } }
const catOut = sh('cat config.json');
console.log('--- cat config.json (raw, between markers) ---');
if (catOut !== null) process.stdout.write('<BEGIN>' + catOut + '<END>\n');
else { console.log('(cat unavailable) node read:'); process.stdout.write('<BEGIN>' + raw2 + '<END>\n'); }

const wcOut = sh('wc -c config.json');
console.log('--- wc -c config.json ---');
console.log(wcOut !== null ? wcOut.trim() : '(wc unavailable) node bytes: ' + Buffer.byteLength(raw2));

console.log('--- key order ---');
console.log(keys); // e.g. [ 'name', 'retries', 'enabled', 'version' ]
console.log('[file bytes]', Buffer.byteLength(raw2));
console.log('[ends with newline]', raw2.endsWith('\n'));

const ok = Object.values(checks).every(Boolean) && Buffer.byteLength(raw2) === 54 && !raw2.endsWith('\n');
if (ok) console.log('DONE: config.json v1->v2 complete; 54 bytes, no trailing newline, key order name,retries,enabled,version, types ok');
else console.log('NOT DONE: verification failed');
